import xarray as xr
import numpy as np
from satpy.readers.fci_l2_nc import FciL2NCAMVFileHandler

class MockNC:
    def __init__(self):
        self.attrs = {"platform": "MTG", "data_source": "FCI"}
        self.mtg_geos_projection = type('obj', (object,), {'attrs': {'longitude_of_projection_origin': '0.0'}})
        # Mock variables
        self.variables = {}

    def __getitem__(self, key):
        # Return a mock DataArray with 'unit' attribute
        return xr.DataArray(np.zeros((10, 10)), dims=("number_of_images", "number_of_winds"), attrs={"unit": "m/s"})

class MockFciL2NCAMVFileHandler(FciL2NCAMVFileHandler):
    def __init__(self, filename):
        self.filename = filename
        self.filename_info = {"channel": "test_channel"}
        self.nc = MockNC()

    def get_dataset(self, dataset_id, dataset_info):
        # This is the original implementation of get_dataset in FciL2NCAMVFileHandler
        # But we want to test the actual class. 
        # Since we are mocking nc, we can just use the real get_dataset.
        return super().get_dataset(dataset_id, dataset_info)

def test_amv_units():
    handler = MockFciL2NCAMVFileHandler("test.nc")
    dataset_info = {"nc_key": "some_var"}
    variable = handler.get_dataset("some_var", dataset_info)

    if "unit" in variable.attrs:
        print("Bug: 'unit' attribute found")
        exit(1)
    if "units" not in variable.attrs:
        print("Bug: 'units' attribute missing")
        exit(1)
    print("Success: 'units' attribute is present and 'unit' is gone")
    exit(0)

if __name__ == "__main__":
    test_amv_units()
